+++ b/training/level-1/L1-023-extension-detect/classifyFile.mjs
@@ -0,0 +1,54 @@
+export function classifyFile(name) {
+  if (typeof name !== 'string' || name.length === 0) {
+    throw new TypeError('Input must be a non-empty string');
+  }
+
+  const path = name;
+  let separator = '/';
+  let lastSeparatorIndex = -1;
+
+  for (let i = 0; i < path.length; i++) {
+    if (path[i] === '/' || path[i] === '\\') {
+      if (lastSeparatorIndex === -1) {
+        lastSeparatorIndex = i;
+        separator = path[i];
+      } else {
+        return { extension: '', category: 'other' };
+      }
+    }
+  }
+
+  const startOfName = lastSeparatorIndex + 1;
+  let namePart = path.slice(startOfName);
+
+  if (namePart.startsWith('.')) {
+    return { extension: '', category: 'other' };
+  }
+
+  const dotIndex = namePart.lastIndexOf(separator === '/' ? '/' : '\\');
+  let extension = '';
+
+  if (dotIndex !== -1) {
+    extension = namePart.slice(dotIndex + 1).toLowerCase();
+  } else {
+    return { extension: '', category: 'other' };
+  }
+
+  const categories = {
+    image: ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'svg'],
+    video: ['mp4', 'mov', 'avi', 'mkv', 'webm'],
+    audio: ['mp3', 'wav', 'flac', 'aac', 'ogg', 'm4a'],
+    document: ['pdf', 'doc', 'docx', 'txt', 'md', 'rtf'],
+    data: ['csv', 'json', 'xml', 'yaml', 'yml'],
+    archive: ['zip', 'rar', '7z', 'tar', 'gz', 'bz2'],
+    code: ['js', 'mjs', 'cjs', 'ts', 'tsx', 'jsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'htm', 'sh', 'ps1']
+  };
+
+  for (const [cat, exts] of Object.entries(categories)) {
+    if (exts.includes(extension)) {
+      return { extension, category: cat };
+    }
+  }
+
+  return { extension, category: 'other' };
+}

